package com.swingtrade.data.entity;

import com.swingtrade.domain.LlmAnalysisResult;
import jakarta.persistence.*;
import java.time.LocalDate;
import java.util.List;
import java.util.UUID;

@Entity @Table(name="llm_analysis_result", uniqueConstraints=@UniqueConstraint(name="uq_llm_analysis_result_symbol_date",columnNames={"symbol","analysis_date"}))
public class LlmAnalysisResultEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private UUID runId; private String symbol; @Column(name="analysis_date") private LocalDate analysisDate; private String recommendation; private Double confidence; @Column(columnDefinition="TEXT") private String narrative; @Column(name="key_drivers",columnDefinition="TEXT[]") private String[] keyDrivers; @Column(name="bullish_factors",columnDefinition="TEXT[]") private String[] bullishFactors; @Column(name="bearish_factors",columnDefinition="TEXT[]") private String[] bearishFactors; private Integer compositeScore; private String compositeSignal; private boolean success; private boolean fallbackUsed; @Column(columnDefinition="TEXT") private String errorMessage;
 public LlmAnalysisResultEntity(){}
 public static LlmAnalysisResultEntity fromDomain(LlmAnalysisResult r){var e=new LlmAnalysisResultEntity();e.id=r.id();e.runId=UUID.fromString(r.runId());e.symbol=r.symbol();e.analysisDate=r.analysisDate();e.recommendation=r.recommendation();e.confidence=r.confidence();e.narrative=r.narrative();e.keyDrivers=array(r.keyDrivers());e.bullishFactors=array(r.bullishFactors());e.bearishFactors=array(r.bearishFactors());e.compositeScore=r.compositeScore();e.compositeSignal=r.compositeSignal();e.success=r.success();e.fallbackUsed=r.fallbackUsed();e.errorMessage=r.errorMessage();return e;}
 private static String[] array(List<String> v){return v==null?null:v.toArray(String[]::new);} private static List<String> list(String[] v){return v==null?List.of():List.of(v);}
 public LlmAnalysisResult toDomain(){return new LlmAnalysisResult(id,runId.toString(),symbol,analysisDate,recommendation,confidence,narrative,list(keyDrivers),list(bullishFactors),list(bearishFactors),compositeScore,compositeSignal,success,fallbackUsed,errorMessage);}
 public Long getId(){return id;} public void setId(Long v){id=v;} public String getSymbol(){return symbol;} public void setSymbol(String v){symbol=v;} public LocalDate getAnalysisDate(){return analysisDate;} public void setAnalysisDate(LocalDate v){analysisDate=v;}
 public UUID getRunId(){return runId;} public void setRunId(UUID v){runId=v;} public String getRecommendation(){return recommendation;} public void setRecommendation(String v){recommendation=v;} public Double getConfidence(){return confidence;} public void setConfidence(Double v){confidence=v;} public String getNarrative(){return narrative;} public void setNarrative(String v){narrative=v;} public String[] getKeyDrivers(){return keyDrivers;} public void setKeyDrivers(String[] v){keyDrivers=v;} public String[] getBullishFactors(){return bullishFactors;} public void setBullishFactors(String[] v){bullishFactors=v;} public String[] getBearishFactors(){return bearishFactors;} public void setBearishFactors(String[] v){bearishFactors=v;} public Integer getCompositeScore(){return compositeScore;} public void setCompositeScore(Integer v){compositeScore=v;} public String getCompositeSignal(){return compositeSignal;} public void setCompositeSignal(String v){compositeSignal=v;} public boolean isSuccess(){return success;} public void setSuccess(boolean v){success=v;} public boolean isFallbackUsed(){return fallbackUsed;} public void setFallbackUsed(boolean v){fallbackUsed=v;} public String getErrorMessage(){return errorMessage;} public void setErrorMessage(String v){errorMessage=v;}
}
